/* Herramienta de Creación de Políticas - Versión Optimizada */
let fetch;
try {
    fetch = global.fetch || require('node-fetch');
} catch (e) {
    console.log("Error al cargar fetch, intentando usar global...");
    fetch = global.fetch;
}

// Usamos el nombre del servicio 'n8n' para comunicación interna en Docker
const webhookUrl = "http://n8n:5678/webhook/ejecutar-fleet";

const options = {
    method: 'POST',
    headers: {
        'Content-Type': 'application/json'
    },
    body: JSON.stringify({ 
        name: $name, 
        query: $query, 
        description: $description, 
        resolution: $resolution, 
        platform: $platform, 
        action: "create_policy" 
    })
};

try {
    const response = await fetch(webhookUrl, options);

    if (response.ok) {
        return "Política creada exitosamente en Fleet.";
    } else {
        const errorText = await response.text();
        return `Error al crear política: ${response.status} - ${errorText}`;
    }
} catch (error) {
    return `Error técnico de conexión: ${error.message}. Asegúrate de que el contenedor de n8n esté activo.`;
}
